eses is negative, accounting style.\n    Rows with a missing or empty amount are skipped, as are blank lines.\n    \"\"\"\n    totals = {}\n    for line in csv_text.strip().splitlines()[1:]:\n        parts = line.split(\",\")\n        cat = parts[1]\n        amount = float(parts[2])\n        totals[cat] = totals.get(cat, 0) + amount\n    return totals\n"}],"path":"src/expenses.py"}"}}
